// What the team's extensions add to the builder's instructions: each
// installed extension may bring guides (Markdown files in its own folder)
// that the builder reads before it works, so a rule of the team's own (how a
// kind of change is done here) holds for every card without being repeated.
import { join } from "node:path";
import { FACTORY_FOLDER, loadFactory, } from "@software-factory/core";
// The guides of the factory's installed extensions meant for this agent,
// read from the working copy (the card's branch may change them).
export function guidesFor(copy, available, agent) {
    const loaded = loadFactory(join(copy, FACTORY_FOLDER), available);
    if ("problem" in loaded)
        return [];
    return loaded.extensions
        .flatMap((extension) => extension.guides)
        .filter((guide) => guide.agent === agent);
}
// The prompt, with the guides it must read first (before its answer's
// section); unchanged without any.
export function withGuides(prompt, guides) {
    if (guides.length === 0)
        return prompt;
    const list = guides
        .map((guide) => `- ${guide.title}: \`${guide.file}\``)
        .join("\n");
    const section = `## The team's own guides

The team's extensions add these to your instructions. Read each one before you start and follow it:

${list}`;
    const at = prompt.lastIndexOf("## Your answer");
    return at < 0
        ? `${prompt}\n\n${section}`
        : `${prompt.slice(0, at)}${section}\n\n${prompt.slice(at)}`;
}
